<template>
	<section v-if="vehicle" class="vehicle-page">
		<RouterLink class="back-link" to="/garage">← Back to garage</RouterLink>
		<div class="detail-heading"><div><span class="section-kicker">VEHICLE OVERVIEW</span><h2>{{ vehicle.make }} {{ vehicle.model }}</h2><p>{{ vehicle.year }} · {{ vehicle.engine }} · {{ vehicle.fuelType }}</p></div><div class="heading-actions"><a v-if="vehicle.manualUrl" class="manual-button" :href="vehicle.manualUrl" target="_blank" rel="noopener noreferrer"><span>▣</span> Owner's manual</a><button class="edit-button" type="button">Edit vehicle</button></div></div>
		<div class="hero-detail"><div class="detail-image" :class="vehicle.id"><span>{{ vehicle.make.charAt(0) }}{{ vehicle.model.charAt(0) }}</span></div><div class="hero-copy"><span class="section-kicker">CURRENT ODOMETER</span><strong>{{ formatNumber(vehicle.odometer) }} <small>km</small></strong><p>{{ vehicle.color }} · Owned since 2021</p></div></div>
		<div class="detail-stats"><article><span>TOTAL COST</span><strong>{{ formatCurrency(vehicle.ownershipCost) }}</strong><small>since purchase</small></article><article><span>AVG. FUEL</span><strong>7.2 <small>L/100km</small></strong><small>last 12 months</small></article><article><span>LAST SERVICE</span><strong>03 Sep</strong><small>Oil + filter change</small></article></div>
		<div class="activity-heading"><div><span class="section-kicker">SERVICE HISTORY</span><h3>Recent activity</h3></div><button class="primary-button" type="button"><span>+</span> Add record</button></div>
		<div class="activity-list"><article v-for="record in records" :key="record.id" class="activity-item"><time>{{ formatDate(record.date) }}</time><div class="activity-icon">{{ record.category.name === 'Engine' ? '⚙' : '✦' }}</div><div class="activity-main"><strong>{{ record.description }}</strong><span>{{ record.odometer.toLocaleString() }} km · {{ record.performedBy === 'owner' ? 'DIY' : 'Workshop' }}</span></div><strong class="activity-cost">{{ formatCurrency(record.cost) }}</strong></article></div>
	</section>
	<section v-else class="empty-state"><h2>Vehicle not found</h2><RouterLink to="/garage">Return to garage</RouterLink></section>
</template>

<script setup lang="ts">
import { computed } from 'vue'
import { useRoute } from 'vue-router'
import { useVehiclesStore } from '../stores/vehicles'
import { maintenanceRecords } from '../stores/maintenance'

const route = useRoute()
const vehicleStore = useVehiclesStore()
const vehicle = computed(() => vehicleStore.findById(String(route.params.vehicleId)))
const records = computed(() => maintenanceRecords.filter((record) => record.vehicleId === vehicle.value?.id))
const formatNumber = (value: number) => new Intl.NumberFormat('en-US').format(value)
const formatCurrency = (value: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(value)
const formatDate = (value: string) => new Intl.DateTimeFormat('en-US', { month: 'short', day: '2-digit' }).format(new Date(`${value}T12:00:00`))
</script>

